class DeviceManagementServicer(devices_pb2_grpc.DeviceServiceServicer):
    async def PushFirmwareUpdate(self, request, context):
        caller = await verify_grpc_caller(context)
        async with AsyncSessionLocal() as session:
            device = await session.get(IoTDevice, request.device_uuid)
            if not device:
                await context.abort(grpc.StatusCode.NOT_FOUND, "Device not found")
            if device.org_id != caller.org_id:
                await context.abort(grpc.StatusCode.PERMISSION_DENIED, "Device does not belong to caller organization")
            await dispatch_ota_job(device.mac_address, request.firmware_url)
            return devices_pb2.PushResponse(status="dispatched")
